INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C1','kor',2,2,'u8',1,'경험을 시나 노래로 표현하면 좋은 점 — 겪은 일을 되돌아보고, 다른 사람에게 실감 나게 전하며, 그때 기분을 잘 나타낼 수 있음을 알기(시는 짧게만 쓴 글도, 다 적은 글도 아님)',ARRAY['2국05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C2','kor',2,2,'u8',3,'작품에 담긴 경험 파악하기 — 「우리 반 쉬는 시간」·「눈 내린 등굣길」·「눈 온 아침」·「함께 걸어 좋은 길」을 읽거나 듣고 글쓴이가 겪은 일과 느낌을 작품에서 찾기',ARRAY['2국05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C3','kor',2,2,'u8',3,'빗대어 표현한 말 이해하기 — 눈 밟는 소리=오리 우는 소리, 걷는 아이들=오리, 운동장=호수처럼 빗댄 말이 무엇을 가리키는지 알고, 내 경험도 무엇에 빗대어 나타내기',ARRAY['2국05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C4','kor',2,2,'u8',3,'같은 경험을 다르게 표현한 작품 견주기 — 「눈 내린 등굣길」과 「눈 온 아침」처럼 비슷한 경험도 무엇에 눈길을 두느냐에 따라 다른 작품이 됨을 알고 같은 점·다른 점 말하기',ARRAY['2국05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C5','kor',2,2,'u8',3,'장면을 상상하며 낭송·발표하기 — 시나 노래의 장면을 떠올리며 리듬을 살려 낭송하거나 몸으로 표현하고, 노래가 부담스러우면 낭독하기(잘 부르기보다 장면 전하기)',ARRAY['2국01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C6','kor',2,2,'u8',5,'노랫말의 특징 — 줄글과 견주어 노랫말은 경험에서 중요한 낱말만 골라 간결하게 쓰고, 비슷한 표현을 되풀이해 리듬과 강조를 만듦을 알기',ARRAY['2국03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C7','kor',2,2,'u8',5,'경험을 담아 노랫말 바꾸어 쓰기 — 누구와, 어디를 지나, 어떤 느낌이었는지 함께 한 경험을 떠올려 노랫말을 바꾸어 쓰기(글자 수에 매이지 않음, 어려우면 장소만 일부 바꾸기)',ARRAY['2국03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C8','kor',2,2,'u8',7,'이야기의 내용과 사건의 차례 — 「빈집에 온 손님」·「오, 미지의 택배」에서 인물이 겪은 일을 찾고, 일이 일어난 차례대로 정리하기',ARRAY['2국05-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C9','kor',2,2,'u8',7,'인물의 성격과 마음 파악하기 — 인물의 말과 행동에서 성격(책임감 등)과 마음을 찾고, 그렇게 생각한 근거를 작품 속 구절에서 대기',ARRAY['2국05-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C10','kor',2,2,'u8',7,'이어질 이야기 상상하기 — 이야기의 흐름과 인물의 성격을 생각하며 사건이 이어지도록 뒷이야기를 상상하고 장면으로 나누어 쓰기(원작과 같을 필요도, 엉뚱할 필요도 없음)',ARRAY['2국05-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C11','kor',2,2,'u8',9,'상상한 이야기 발표하고 견주며 듣기 — 상상한 이야기를 바른 자세로 발표하고, 친구 이야기가 흐름과 성격에 맞는지, 내 이야기와 무엇이 같고 다른지 생각하며 듣고 느낌 말하기',ARRAY['2국01-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C12','kor',2,2,'u8',11,'그림책·시화집 만들어 나누기 — 이야기가 담긴 책을 골라 줄거리 소개·장면 나누기·그림으로 그림책을 만들어 전시하고, 그림보다 이야기를 보고 친구 작품을 칭찬하기(정지 장면·시화집 포함)',ARRAY['2국06-01']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u8-C13','kor',2,2,'u8',11,'낱말의 뜻과 토박이말 — 도란도란·인생·제품·인공의 뜻을 이야기 속 쓰임으로 짐작하고, 토박이말 미리내·으뜸·너울·갈무리의 뜻을 알아 짧은 문장 만들기(기초 다지기)',ARRAY['2국03-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X01','kor',2,'u8',ARRAY['K2-2-u8-C1','K2-2-u8-C6']::text[],'시는 그냥 짧게만 쓰면 되는 글이라고 여긴다','「어떤 순간, 어떤 기분?」을 먼저 정하고 그 느낌이 드러나는 말 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X02','kor',2,'u8',ARRAY['K2-2-u8-C1','K2-2-u8-C6','K2-2-u8-C7']::text[],'겪은 일을 처음부터 끝까지 다 적으면 시나 노랫말이 된다고 여긴다','꼭 필요한 낱말만 남기고 나머지는 지워 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X03','kor',2,'u8',ARRAY['K2-2-u8-C3']::text[],'빗대어 표현한 말을 글자 그대로 받아들인다(진짜 오리, 교실이 진짜 터짐)','「무엇을 무엇처럼 말했지?」 하고 두 가지를 짝 지어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X04','kor',2,'u8',ARRAY['K2-2-u8-C2','K2-2-u8-C8']::text[],'작품에 없는 내용으로 답하거나 작품 속 일을 바꿔 안다','「작품 어디에 있지?」 하고 그 쪽을 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X05','kor',2,'u8',ARRAY['K2-2-u8-C4']::text[],'같은 경험이면 누가 써도 같은 작품이 된다고 여겨 작품의 차이를 보지 못한다','「무엇에 눈길을 두었지?」 — 두 작품의 주인공 장면 비교하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X06','kor',2,'u8',ARRAY['K2-2-u8-C7']::text[],'노랫말을 바꿀 때 원래와 글자 수가 반드시 똑같아야 한다고 여긴다','부르기 쉬운 건 좋지만, 목적은 내 경험을 담는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X07','kor',2,'u8',ARRAY['K2-2-u8-C7']::text[],'원래 노래나 내 경험과 상관없이 아무 말로나 바꾸거나, 그대로 옮겨 쓴다','누구와 · 어디를 · 어떤 느낌 — 세 칸을 내 경험으로 채우기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X08','kor',2,'u8',ARRAY['K2-2-u8-C7']::text[],'친구와 함께 한 일 대신 친구의 생김새·특징만 떠올린다','「친구와 무엇을 했지?」로 생각그물 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X09','kor',2,'u8',ARRAY['K2-2-u8-C10','K2-2-u8-C11']::text[],'이어질 이야기는 원래 작가가 쓴 이야기와 같거나 비슷해야 맞다고 여긴다','원작은 작가의 생각 하나 — 흐름과 성격에 맞으면 다른 길도 좋아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X10','kor',2,'u8',ARRAY['K2-2-u8-C10']::text[],'엉뚱하고 자극적일수록 좋은 이어질 이야기라고 여겨 흐름·인물을 무시한다','「금방울(미지)이라면 정말 이렇게 할까?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X11','kor',2,'u8',ARRAY['K2-2-u8-C10']::text[],'이어질 이야기를 「○○가 찾아왔다.」 같은 한 장면으로 끝낸다','그다음엔? 그래서 마음은? — 사건을 두세 개 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X12','kor',2,'u8',ARRAY['K2-2-u8-C9']::text[],'인물의 성격·마음을 작품 속 근거 없이 느낌으로만 말한다','「어느 말이나 행동에서?」 하고 그 구절 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X13','kor',2,'u8',ARRAY['K2-2-u8-C8','K2-2-u8-C12']::text[],'사건의 차례를 뒤섞거나 줄거리·순서를 빠뜨린다','「먼저 → 그다음 → 마지막」으로 손가락 세며 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X14','kor',2,'u8',ARRAY['K2-2-u8-C5','K2-2-u8-C11','K2-2-u8-C12']::text[],'낭송·발표·그림책에서 노래 솜씨나 그림의 화려함 같은 겉모습만 중요하게 여긴다','잘 부르기·예쁜 그림보다 「장면과 이야기가 전해지나?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u8-X15','kor',2,'u8',ARRAY['K2-2-u8-C13']::text[],'낱말·토박이말의 뜻을 헷갈려 엉뚱한 자리에 쓴다','예문 속 자리에 넣어 보고 말이 되는지 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
