INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L01_basic#2','kor',2,2,'u8','L01','g2_2_kor_u8_L01_basic','lesson_basic','K2-2-u8-C1',1,'mc','auto','229쪽 남자아이는 무엇을 한 경험을 떠올리고 있나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":2,"concept":"K2-2-u8-C1","difficulty":1,"kind":"mc","stem":"229쪽 남자아이는 무엇을 한 경험을 떠올리고 있나요?","options":[{"t":"친구들과 눈사람을 만들고 눈썰매를 탄 경험","correct":true},{"t":"수영장에서 수영한 경험","mis":"K2-2-u8-X04"},{"t":"생일잔치를 한 경험","mis":"K2-2-u8-X04"}],"explanation":["눈 놀이예요.","지도서 318쪽이에요.","머리 위 그림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
