INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L01_challenge#7','kor',2,2,'u8','L01','g2_2_kor_u8_L01_challenge','lesson_challenge','K2-2-u8-C1',3,'mc','auto','시나 노래, 이야기로 경험을 표현해 본 친구는?',ARRAY['K2-2-u8-X02','K2-2-u8-X04']::text[],false,'{"seq":7,"concept":"K2-2-u8-C1","difficulty":3,"kind":"mc","stem":"시나 노래, 이야기로 경험을 표현해 본 친구는?","options":[{"t":"「캠핑 간 날 밤하늘을 보고 느낀 마음을 동시로 써 봤어.」","correct":true},{"t":"「어제 저녁에 밥을 먹었어.」","mis":"K2-2-u8-X02"},{"t":"「나는 키가 130센티미터야.」","mis":"K2-2-u8-X04"}],"explanation":["경험을 시로 썼어요.","지도서 318쪽이에요.","창작 경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L01_challenge#8','kor',2,2,'u8','L01','g2_2_kor_u8_L01_challenge','lesson_challenge','K2-2-u8-C1',4,'sa','auto','경험을 시나 노래로 표현하면 경험한 일을 다른 사람에게 ○○ 나게 전할 수 있어요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u8-C1","difficulty":4,"kind":"sa","stem":"경험을 시나 노래로 표현하면 경험한 일을 다른 사람에게 ○○ 나게 전할 수 있어요. 빈칸 두 글자를 쓰세요.","answer":["실감"],"explanation":["실감이에요.","231쪽 말풍선이에요.","생생하게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L01_challenge#9','kor',2,2,'u8','L01','g2_2_kor_u8_L01_challenge','lesson_challenge','K2-2-u8-C1',4,'essay','teacher','229쪽 — 어떤 경험을 시나 이야기로 표현하고 싶은지 「언제 / 무엇을 / 어떤 기분」을 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u8-C1","difficulty":4,"kind":"essay","stem":"229쪽 — 어떤 경험을 시나 이야기로 표현하고 싶은지 「언제 / 무엇을 / 어떤 기분」을 넣어 쓰세요.","answer_guide":{"answer":"예: 지난 겨울에 친구들과 눈썰매를 탔을 때 바람을 가르며 내려와 정말 신났던 경험을 시로 쓰고 싶다.","scoring_points":["언제·무엇을 했는지 썼어요","그때 기분을 썼어요"]},"explanation":["경험과 기분이에요.","229쪽이에요.","작품의 재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L01_challenge#10','kor',2,2,'u8','L01','g2_2_kor_u8_L01_challenge','lesson_challenge','K2-2-u8-C3',4,'essay','teacher','231쪽 3번 — 우리 반 쉬는 시간의 모습을 「~ 같아」를 넣어 빗대어 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C3","difficulty":4,"kind":"essay","stem":"231쪽 3번 — 우리 반 쉬는 시간의 모습을 「~ 같아」를 넣어 빗대어 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리 반 쉬는 시간은 시장 같아. 여기저기서 친구들이 이야기하는 소리가 들리기 때문이야.","scoring_points":["「~ 같아」로 빗대었어요","까닭을 썼어요"]},"explanation":["빗대어 써요.","231쪽 예시 답안이에요.","까닭과 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L03_basic#1','kor',2,2,'u8','L03','g2_2_kor_u8_L03_basic','lesson_basic','K2-2-u8-C2',1,'mc','auto','「눈 내린 등굣길」에서 쌓인 눈을 밟으면 어떤 소리가 난다고 했나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C2","difficulty":1,"kind":"mc","stem":"「눈 내린 등굣길」에서 쌓인 눈을 밟으면 어떤 소리가 난다고 했나요?","options":[{"t":"오리 우는 소리","correct":true},{"t":"유리창 닦는 소리","mis":"K2-2-u8-X04"},{"t":"북 치는 소리","mis":"K2-2-u8-X04"}],"explanation":["오리 우는 소리예요.","234쪽 예시 답안이에요.","「꽥!」이에요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
