INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L03_challenge#8','kor',2,2,'u8','L03','g2_2_kor_u8_L03_challenge','lesson_challenge','K2-2-u8-C3',4,'sa','auto','「눈 내린 등굣길」에서 쌓인 눈을 밟을 때 나는 소리를 흉내 낸 말을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u8-C3","difficulty":4,"kind":"sa","stem":"「눈 내린 등굣길」에서 쌓인 눈을 밟을 때 나는 소리를 흉내 낸 말을 한 글자로 쓰세요.","answer":["꽥","꽥!"],"explanation":["꽥이에요.","232쪽이에요.","오리 소리예요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L03_challenge#9','kor',2,2,'u8','L03','g2_2_kor_u8_L03_challenge','lesson_challenge','K2-2-u8-C3',4,'essay','teacher','235쪽 5번 — 눈을 밟았던 경험을 떠올려 눈 밟는 소리나 모습을 무엇에 빗대어 재미있게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u8-C3","difficulty":4,"kind":"essay","stem":"235쪽 5번 — 눈을 밟았던 경험을 떠올려 눈 밟는 소리나 모습을 무엇에 빗대어 재미있게 쓰세요.","answer_guide":{"answer":"예: 빠드득빠드득 눈을 밟으면 과자를 씹는 소리가 들린다.","scoring_points":["소리나 모습을 흉내 냈어요","무엇에 빗대었어요"]},"explanation":["빗대어 써요.","235쪽 예시 답안이에요.","내 경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L03_challenge#10','kor',2,2,'u8','L03','g2_2_kor_u8_L03_challenge','lesson_challenge','K2-2-u8-C4',4,'essay','teacher','237쪽 8번 — 「눈 내린 등굣길」과 「눈 온 아침」에 나타난 경험이 어떻게 같고 다른지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C4","difficulty":4,"kind":"essay","stem":"237쪽 8번 — 「눈 내린 등굣길」과 「눈 온 아침」에 나타난 경험이 어떻게 같고 다른지 쓰세요.","answer_guide":{"answer":"예: 두 작품 모두 눈 내린 아침 풍경을 표현했다. 「눈 내린 등굣길」은 친구들과 등교하는 모습을 오리에 빗대었고, 「눈 온 아침」은 눈길에 남은 발자국의 주인을 궁금해했다.","scoring_points":["같은 점을 썼어요","다른 점을 썼어요"]},"explanation":["견주어 써요.","237쪽이에요.","눈길을 둔 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
