INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#3','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C7',3,'ox','auto','노랫말을 바꾸어 쓸 때에는 원래 노랫말과 글자 수가 반드시 똑같아야 한다.',ARRAY['K2-2-u8-X06']::text[],false,'{"seq":3,"concept":"K2-2-u8-C7","difficulty":3,"kind":"ox","stem":"노랫말을 바꾸어 쓸 때에는 원래 노랫말과 글자 수가 반드시 똑같아야 한다.","answer":"X","reason_options":[{"t":"노랫말 창작이 목적이라 글자 수에 매이지 않고 자유롭게 낱말을 고를 수 있어서","correct":true},{"t":"글자 수가 다르면 틀린 노랫말이라서","mis":"K2-2-u8-X06"}],"mis":"K2-2-u8-X06","explanation":["자유롭게요.","지도서 327쪽이에요.","창작이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
