INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#5','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C6',3,'mc','auto','줄글로 된 경험을 노랫말로 바꾸면 어떤 점이 달라지나요?',ARRAY['K2-2-u8-X02','K2-2-u8-X07']::text[],false,'{"seq":5,"concept":"K2-2-u8-C6","difficulty":3,"kind":"mc","stem":"줄글로 된 경험을 노랫말로 바꾸면 어떤 점이 달라지나요?","options":[{"t":"꼭 필요한 낱말만 골라 짧고 리듬 있게 나타내요","correct":true},{"t":"더 길고 자세해져요","mis":"K2-2-u8-X02"},{"t":"경험이 모두 빠져요","mis":"K2-2-u8-X07"}],"explanation":["간결하고 리듬 있게요.","241쪽이에요.","중요한 낱말이에요."],"asset":{"type":"passage","lines":["오늘 친한 친구와 학교에 같이 갔다.","가는 길에 문구점도 보이고 장난감집도 지났다.","날마다 가는 길인데도 친구랑 함께 이야기하면서 가니까","특별하게 느껴졌다."],"title":"『국어』 241쪽 경험을 쓴 줄글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#6','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C7',3,'mc','auto','242쪽 — 할아버지와 즐겁게 산책했던 경험으로 노랫말을 바꿀 때 가장 알맞은 것은?',ARRAY['K2-2-u8-X07']::text[],false,'{"seq":6,"concept":"K2-2-u8-C7","difficulty":3,"kind":"mc","stem":"242쪽 — 할아버지와 즐겁게 산책했던 경험으로 노랫말을 바꿀 때 가장 알맞은 것은?","options":[{"t":"산책하며 지나간 곳, 「할아버지랑」, 그때 느낌으로 바꾸어 써요","correct":true},{"t":"친구 이름을 그대로 두고 장소만 바꿔요","mis":"K2-2-u8-X07"},{"t":"노랫말을 하나도 바꾸지 않아요","mis":"K2-2-u8-X07"}],"explanation":["경험에 맞게요.","242쪽 말풍선이에요.","누구와를 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#7','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C5',3,'mc','auto','노래 부르기가 부담스러운 친구가 바꾼 노랫말을 발표할 때 알맞은 것은?',ARRAY['K2-2-u8-X14']::text[],false,'{"seq":7,"concept":"K2-2-u8-C5","difficulty":3,"kind":"mc","stem":"노래 부르기가 부담스러운 친구가 바꾼 노랫말을 발표할 때 알맞은 것은?","options":[{"t":"노랫말을 또박또박 낭독해도 돼요","correct":true},{"t":"노래를 잘 부를 때까지 발표하면 안 돼요","mis":"K2-2-u8-X14"},{"t":"친구들이 웃으면 그만둬요","mis":"K2-2-u8-X14"}],"explanation":["낭독해도 돼요.","지도서 327쪽이에요.","노랫말이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#8','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C13',4,'sa','auto','여러 사람이 크지 않은 목소리로 정답게 이야기하는 소리나 모양을 나타내는 네 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u8-C13","difficulty":4,"kind":"sa","stem":"여러 사람이 크지 않은 목소리로 정답게 이야기하는 소리나 모양을 나타내는 네 글자 낱말을 쓰세요.","answer":["도란도란"],"explanation":["도란도란이에요.","240쪽이에요.","노랫말 속 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#9','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C7',4,'essay','teacher','243쪽 — 반가운 사람과 함께 걸었던 일을 떠올려 「지나간 곳 두 군데 · 가는 곳 · 함께 간 사람 · 그때 느낌」을 넣어 노랫말 한 줄을 바꾸어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u8-C7","difficulty":4,"kind":"essay","stem":"243쪽 — 반가운 사람과 함께 걸었던 일을 떠올려 「지나간 곳 두 군데 · 가는 곳 · 함께 간 사람 · 그때 느낌」을 넣어 노랫말 한 줄을 바꾸어 쓰세요.","answer_guide":{"answer":"예: 놀이터를 지나고 빵집 지나서 / 도서관 가는 길 언니랑 함께 가서 설레는 길","scoring_points":["지나간 곳과 가는 곳이 있어요","함께 간 사람과 느낌이 있어요"]},"explanation":["내 경험을 담아요.","243쪽이에요.","글자 수는 자유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L05_challenge#10','kor',2,2,'u8','L05','g2_2_kor_u8_L05_challenge','lesson_challenge','K2-2-u8-C6',4,'essay','teacher','241쪽 줄글을 읽고, 줄글과 노랫말이 어떻게 다른지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C6","difficulty":4,"kind":"essay","stem":"241쪽 줄글을 읽고, 줄글과 노랫말이 어떻게 다른지 두 가지 쓰세요.","answer_guide":{"answer":"예: 노랫말은 경험이나 느낌을 길게 늘여 쓰지 않고 간결하게 표현했다. 비슷한 표현을 반복해 노래를 부르는 듯한 느낌이 든다.","scoring_points":["간결함을 썼어요","반복이나 리듬을 썼어요"]},"explanation":["특징이에요.","241쪽 예시 답안이에요.","두 가지예요."],"asset":{"type":"passage","lines":["오늘 친한 친구와 학교에 같이 갔다.","가는 길에 문구점도 보이고 장난감집도 지났다.","날마다 가는 길인데도 친구랑 함께 이야기하면서 가니까","특별하게 느껴졌다."],"title":"『국어』 241쪽 경험을 쓴 줄글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_basic#1','kor',2,2,'u8','L07','g2_2_kor_u8_L07_basic','lesson_basic','K2-2-u8-C8',1,'mc','auto','엄마, 아빠께서 금방울에게 하신 말씀은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"엄마, 아빠께서 금방울에게 하신 말씀은?","options":[{"t":"동생들을 잘 돌보라고 하셨어요","correct":true},{"t":"빈집을 청소하라고 하셨어요","mis":"K2-2-u8-X04"},{"t":"할머니 댁으로 오라고 하셨어요","mis":"K2-2-u8-X04"}],"explanation":["동생 돌보기예요.","249쪽 예시 답안이에요.","이야기 첫머리예요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_basic#2','kor',2,2,'u8','L07','g2_2_kor_u8_L07_basic','lesson_basic','K2-2-u8-C8',1,'mc','auto','금방울이 집에 왔을 때 동생들은 무엇을 하고 있었나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":2,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"금방울이 집에 왔을 때 동생들은 무엇을 하고 있었나요?","options":[{"t":"난롯가에서 몸을 말리고 있었어요","correct":true},{"t":"빈집에서 놀고 있었어요","mis":"K2-2-u8-X04"},{"t":"잠을 자고 있었어요","mis":"K2-2-u8-X04"}],"explanation":["난롯가예요.","249쪽 예시 답안이에요.","마음이 놓였어요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
