INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_challenge#5','kor',2,2,'u8','L07','g2_2_kor_u8_L07_challenge','lesson_challenge','K2-2-u8-C9',3,'mc','auto','인물의 성격을 이야기할 때 알맞은 방법은?',ARRAY['K2-2-u8-X12']::text[],false,'{"seq":5,"concept":"K2-2-u8-C9","difficulty":3,"kind":"mc","stem":"인물의 성격을 이야기할 때 알맞은 방법은?","options":[{"t":"이야기 속 어느 말이나 행동에서 그렇게 느꼈는지 찾아 까닭과 함께 말해요","correct":true},{"t":"그냥 느낌만 말해요","mis":"K2-2-u8-X12"},{"t":"그림 색깔만 보고 말해요","mis":"K2-2-u8-X12"}],"explanation":["근거를 찾아요.","지도서 330쪽이에요.","작품 속 구절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_challenge#6','kor',2,2,'u8','L07','g2_2_kor_u8_L07_challenge','lesson_challenge','K2-2-u8-C10',3,'mc','auto','금방울이 여러분과 비슷한 나이라는 것을 생각하면 어울리는 이어질 이야기는?',ARRAY['K2-2-u8-X10']::text[],false,'{"seq":6,"concept":"K2-2-u8-C10","difficulty":3,"kind":"mc","stem":"금방울이 여러분과 비슷한 나이라는 것을 생각하면 어울리는 이어질 이야기는?","options":[{"t":"무서워도 동생을 위해 조심조심 빈집에 가 보는 이야기","correct":true},{"t":"금방울이 덩치를 번쩍 들어 던지는 이야기","mis":"K2-2-u8-X10"},{"t":"금방울이 마법사로 변하는 이야기","mis":"K2-2-u8-X10"}],"explanation":["나이에 맞아요.","지도서 331쪽이에요.","허황되지 않게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_challenge#7','kor',2,2,'u8','L07','g2_2_kor_u8_L07_challenge','lesson_challenge','K2-2-u8-C11',3,'mc','auto','251쪽 6~7번 — 친구가 상상한 이야기를 들을 때 알맞은 태도는?',ARRAY['K2-2-u8-X09','K2-2-u8-X10']::text[],false,'{"seq":7,"concept":"K2-2-u8-C11","difficulty":3,"kind":"mc","stem":"251쪽 6~7번 — 친구가 상상한 이야기를 들을 때 알맞은 태도는?","options":[{"t":"인물의 성격을 잘 생각했는지, 흐름에 맞게 이어지는지 생각하며 들어요","correct":true},{"t":"내 이야기와 다르면 틀렸다고 말해요","mis":"K2-2-u8-X09"},{"t":"가장 무서운 이야기만 칭찬해요","mis":"K2-2-u8-X10"}],"explanation":["생각하며 들어요.","지도서 331쪽이에요.","다른 점에 주목해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_challenge#8','kor',2,2,'u8','L07','g2_2_kor_u8_L07_challenge','lesson_challenge','K2-2-u8-C8',4,'sa','auto','금방울이 작은방울을 업고 불러 준 노래는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u8-C8","difficulty":4,"kind":"sa","stem":"금방울이 작은방울을 업고 불러 준 노래는 무엇인가요? 세 글자로 쓰세요.","answer":["자장가"],"explanation":["자장가예요.","249쪽이에요.","잠을 재워요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_challenge#9','kor',2,2,'u8','L07','g2_2_kor_u8_L07_challenge','lesson_challenge','K2-2-u8-C10',4,'essay','teacher','250쪽 5번 — 「금방울이 문틈으로 밖을 살펴봤는데 낯선 손님은 없고 어둠뿐이었다.」 뒤에 이어질 이야기를 두 장면으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u8-C10","difficulty":4,"kind":"essay","stem":"250쪽 5번 — 「금방울이 문틈으로 밖을 살펴봤는데 낯선 손님은 없고 어둠뿐이었다.」 뒤에 이어질 이야기를 두 장면으로 쓰세요.","answer_guide":{"answer":"예: 작은방울이 계속 칭얼대자 금방울은 담요를 가지러 빈집으로 갔다. → 빈집 안에는 비에 젖은 덩치가 담요를 덮고 떨고 있었고, 금방울은 깜짝 놀라 뒷걸음질 쳤다.","scoring_points":["흐름에 맞게 이어졌어요","두 장면으로 나누었어요","인물의 성격에 어울려요"]},"explanation":["두 장면이에요.","250쪽이에요.","사건을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L07_challenge#10','kor',2,2,'u8','L07','g2_2_kor_u8_L07_challenge','lesson_challenge','K2-2-u8-C9',4,'essay','teacher','250쪽 4번 — 「빈집에 온 손님」에 나온 인물 한 명을 골라 성격을 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C9","difficulty":4,"kind":"essay","stem":"250쪽 4번 — 「빈집에 온 손님」에 나온 인물 한 명을 골라 성격을 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 쓰세요.","answer_guide":{"answer":"예: 은방울은 겁이 많다. 빈집에서 언니를 기다리며 무척 무서웠다고 투덜댔기 때문이다.","scoring_points":["인물의 성격을 썼어요","이야기에서 근거를 찾았어요"]},"explanation":["근거와 함께요.","250쪽 말풍선이에요.","작품 속에서요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_basic#1','kor',2,2,'u8','L09','g2_2_kor_u8_L09_basic','lesson_basic','K2-2-u8-C8',1,'mc','auto','4월 3일에 미지가 어른이 되었다고 생각한 까닭은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"4월 3일에 미지가 어른이 되었다고 생각한 까닭은?","options":[{"t":"아홉 살 인생에 첫 택배가 도착했기 때문에","correct":true},{"t":"생일이 지나서","mis":"K2-2-u8-X04"},{"t":"키가 커서","mis":"K2-2-u8-X04"}],"explanation":["첫 택배예요.","256쪽 예시 답안이에요.","미지가 정한 때예요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_basic#2','kor',2,2,'u8','L09','g2_2_kor_u8_L09_basic','lesson_basic','K2-2-u8-C8',1,'mc','auto','택배 상자 속에 들어 있던 것은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":2,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"택배 상자 속에 들어 있던 것은?","options":[{"t":"하얀 끈 운동화와 제품 설명서","correct":true},{"t":"반짝이는 장난감 로봇","mis":"K2-2-u8-X04"},{"t":"편지와 사탕","mis":"K2-2-u8-X04"}],"explanation":["운동화와 설명서예요.","254쪽이에요.","심심해 보이는 운동화예요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_basic#3','kor',2,2,'u8','L09','g2_2_kor_u8_L09_basic','lesson_basic','K2-2-u8-C13',1,'mc','auto','257쪽 — 「인생」의 뜻은?',ARRAY['K2-2-u8-X15']::text[],false,'{"seq":3,"concept":"K2-2-u8-C13","difficulty":1,"kind":"mc","stem":"257쪽 — 「인생」의 뜻은?","options":[{"t":"사람이 세상을 살아가는 일. 또는 그 기간","correct":true},{"t":"재료를 써서 만든 물건","mis":"K2-2-u8-X15"},{"t":"사람이 만들어 내거나 꾸며 낸 것","mis":"K2-2-u8-X15"}],"explanation":["살아가는 일이에요.","257쪽 예시 답안이에요.","아홉 살 인생이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
