INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_basic#5','kor',2,2,'u8','L09','g2_2_kor_u8_L09_basic','lesson_basic','K2-2-u8-C8',2,'mc','auto','택배 상자 속 운동화가 특별한 점은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":5,"concept":"K2-2-u8-C8","difficulty":2,"kind":"mc","stem":"택배 상자 속 운동화가 특별한 점은?","options":[{"t":"하늘나라에 있는 누군가에게 데려다줘요","correct":true},{"t":"신으면 하늘을 날아다녀요","mis":"K2-2-u8-X04"},{"t":"신으면 키가 커져요","mis":"K2-2-u8-X04"}],"explanation":["데려다줘요.","256쪽 예시 답안이에요.","설명서에 있어요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_basic#6','kor',2,2,'u8','L09','g2_2_kor_u8_L09_basic','lesson_basic','K2-2-u8-C8',2,'match','auto','257쪽 — 일이 일어난 차례대로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-2-u8-C8","difficulty":2,"kind":"match","stem":"257쪽 — 일이 일어난 차례대로 이어 보세요.","pairs":[{"l":"첫째","r":"미지에게 택배가 도착했다"},{"l":"둘째","r":"미지는 경비실에서 파란색 택배 상자를 찾아왔다"},{"l":"셋째","r":"택배 상자 안에 운동화가 들어 있었다"},{"l":"넷째","r":"미지는 제품 설명서를 발견하고 읽었다"},{"l":"다섯째","r":"미지는 운동화를 신고 폴짝폴짝 세 번 뛰었다"}],"mis":"K2-2-u8-X13","explanation":["차례대로요.","257쪽 예시 답안이에요.","사건의 흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_basic#7','kor',2,2,'u8','L09','g2_2_kor_u8_L09_basic','lesson_basic','K2-2-u8-C10',2,'mc','auto','지도서 335쪽 — 이어질 장면을 상상할 때 가장 자연스럽게 느껴지는 장면은?',ARRAY['K2-2-u8-X10']::text[],false,'{"seq":7,"concept":"K2-2-u8-C10","difficulty":2,"kind":"mc","stem":"지도서 335쪽 — 이어질 장면을 상상할 때 가장 자연스럽게 느껴지는 장면은?","options":[{"t":"사건의 흐름과 인물의 성격에 알맞은 장면","correct":true},{"t":"가장 놀랍고 엉뚱한 장면","mis":"K2-2-u8-X10"},{"t":"앞 이야기와 상관없는 장면","mis":"K2-2-u8-X10"}],"explanation":["흐름과 성격이에요.","지도서 335쪽이에요.","자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
