INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_challenge#6','kor',2,2,'u8','L09','g2_2_kor_u8_L09_challenge','lesson_challenge','K2-2-u8-C9',3,'mc','auto','미지의 마음을 알 수 있는 부분으로 알맞은 것은?',ARRAY['K2-2-u8-X12']::text[],false,'{"seq":6,"concept":"K2-2-u8-C9","difficulty":3,"kind":"mc","stem":"미지의 마음을 알 수 있는 부분으로 알맞은 것은?","options":[{"t":"설명서를 읽고 머릿속이 시끄러워지다가 어느새 운동화를 신고 뛰고 있었던 것","correct":true},{"t":"경비 아저씨가 밥 먹으러 간 것","mis":"K2-2-u8-X12"},{"t":"상자가 파란색인 것","mis":"K2-2-u8-X12"}],"explanation":["설레는 마음이에요.","256쪽이에요.","행동에서 찾아요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_challenge#7','kor',2,2,'u8','L09','g2_2_kor_u8_L09_challenge','lesson_challenge','K2-2-u8-C11',3,'mc','auto','친구들의 발표를 들으며 할 일로 알맞은 것은?',ARRAY['K2-2-u8-X09','K2-2-u8-X14']::text[],false,'{"seq":7,"concept":"K2-2-u8-C11","difficulty":3,"kind":"mc","stem":"친구들의 발표를 들으며 할 일로 알맞은 것은?","options":[{"t":"내 이야기와 비슷한 점과 다른 점을 생각하며 들어요","correct":true},{"t":"내 이야기와 다르면 틀렸다고 말해요","mis":"K2-2-u8-X09"},{"t":"그림이 가장 예쁜 이야기만 좋다고 해요","mis":"K2-2-u8-X14"}],"explanation":["견주며 들어요.","지도서 339쪽이에요.","비슷한 점·다른 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_challenge#8','kor',2,2,'u8','L09','g2_2_kor_u8_L09_challenge','lesson_challenge','K2-2-u8-C13',4,'sa','auto','사람이 세상을 살아가는 일, 또는 그 기간을 뜻하는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u8-C13","difficulty":4,"kind":"sa","stem":"사람이 세상을 살아가는 일, 또는 그 기간을 뜻하는 두 글자 낱말을 쓰세요.","answer":["인생"],"explanation":["인생이에요.","257쪽이에요.","아홉 살 인생이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_challenge#9','kor',2,2,'u8','L09','g2_2_kor_u8_L09_challenge','lesson_challenge','K2-2-u8-C10',4,'essay','teacher','지도서 349쪽 평가 — 「오, 미지의 택배」에서 미지가 하늘나라로 가서 만나고 싶은 대상을 정하고, 이어질 이야기를 장면 두세 개로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u8-C10","difficulty":4,"kind":"essay","stem":"지도서 349쪽 평가 — 「오, 미지의 택배」에서 미지가 하늘나라로 가서 만나고 싶은 대상을 정하고, 이어질 이야기를 장면 두세 개로 쓰세요.","answer_guide":{"answer":"예: 미지는 눈앞이 노래질 때까지 달려 하늘나라에 닿았다. → 그곳에서 예전에 키우던 강아지를 만나 꼭 안아 주었다. → 30분이 다 되어 가자 미지는 다시 만나러 오겠다며 손을 흔들었다.","scoring_points":["만나고 싶은 대상을 정했어요","흐름에 맞게 장면을 이었어요","미지의 마음이 드러나요"]},"explanation":["흐름과 성격이에요.","지도서 348쪽이에요.","어색해도 까닭을 설명하면 돼요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L09_challenge#10','kor',2,2,'u8','L09','g2_2_kor_u8_L09_challenge','lesson_challenge','K2-2-u8-C11',4,'essay','teacher','251쪽 7번 — 친구가 상상한 이어질 이야기를 듣고 드는 생각이나 느낌을 「내 이야기와 다른 점」을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C11","difficulty":4,"kind":"essay","stem":"251쪽 7번 — 친구가 상상한 이어질 이야기를 듣고 드는 생각이나 느낌을 「내 이야기와 다른 점」을 넣어 쓰세요.","answer_guide":{"answer":"예: 나는 미지가 할머니를 만난다고 상상했는데 친구는 키우던 강아지를 만난다고 해서 새로웠다. 미지가 강아지를 많이 그리워했을 것 같아 마음이 찡했다.","scoring_points":["친구 이야기에 대한 생각이에요","내 이야기와 견주었어요"]},"explanation":["견주어 써요.","251쪽이에요.","생각이나 느낌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
