INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L11_challenge#9','kor',2,2,'u8','L11','g2_2_kor_u8_L11_challenge','lesson_challenge','K2-2-u8-C13',4,'essay','teacher','264쪽 2번 — 토박이말 「미리내·으뜸·너울·갈무리」 가운데 하나를 골라 짧은 문장을 만드세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u8-C13","difficulty":4,"kind":"essay","stem":"264쪽 2번 — 토박이말 「미리내·으뜸·너울·갈무리」 가운데 하나를 골라 짧은 문장을 만드세요.","answer_guide":{"answer":"예: 우리 반은 청소를 끝내고 학급 문고를 깔끔하게 갈무리했다.","scoring_points":["토박이말을 하나 골랐어요","뜻에 맞게 문장을 만들었어요"]},"explanation":["짧은 문장이에요.","264쪽이에요.","뜻에 맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_L11_challenge#10','kor',2,2,'u8','L11','g2_2_kor_u8_L11_challenge','lesson_challenge','K2-2-u8-C12',4,'essay','teacher','좋아하는 이야기를 하나 골라 그림책 첫 면에 쓸 줄거리 소개를 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C12","difficulty":4,"kind":"essay","stem":"좋아하는 이야기를 하나 골라 그림책 첫 면에 쓸 줄거리 소개를 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 「흥부와 놀부」는 마음씨 착한 흥부가 다친 제비를 고쳐 주고 복을 받는 이야기이다. 욕심 많은 놀부는 일부러 제비 다리를 다치게 했다가 벌을 받는다.","scoring_points":["이야기 제목이 있어요","줄거리를 간단히 썼어요"]},"explanation":["줄거리 소개예요.","지도서 341쪽이에요.","첫 면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#1','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C2',1,'mc','auto','시에서 쉬는 시간에 들린다고 한 소리는?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C2","difficulty":1,"kind":"mc","stem":"시에서 쉬는 시간에 들린다고 한 소리는?","options":[{"t":"아이들이 이야기하고 떠들고 웃고 뛰어다니는 소리","correct":true},{"t":"선생님이 책을 읽어 주시는 소리","mis":"K2-2-u8-X04"},{"t":"빗소리와 바람 소리","mis":"K2-2-u8-X04"}],"explanation":["여러 소리예요.","230쪽이에요.","교실이 가득해요."],"asset":{"type":"scene","icon":"🏫","text":"『국어』 230쪽 「우리 반 쉬는 시간」(어린이 시) — 쉬는 시간마다 교실이 아이들 소리로 가득 차는 모습을 쓴 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#2','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C3',1,'mc','auto','시에서 눈 쌓인 운동장을 무엇처럼 보인다고 했나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":2,"concept":"K2-2-u8-C3","difficulty":1,"kind":"mc","stem":"시에서 눈 쌓인 운동장을 무엇처럼 보인다고 했나요?","options":[{"t":"오리들이 있는 널따란 호수","correct":true},{"t":"하얀 솜사탕","mis":"K2-2-u8-X04"},{"t":"커다란 빵","mis":"K2-2-u8-X04"}],"explanation":["호수예요.","234쪽이에요.","빗댄 말이에요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#3','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C8',1,'mc','auto','엄마, 아빠께서 금방울에게 하신 말씀은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":3,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"엄마, 아빠께서 금방울에게 하신 말씀은?","options":[{"t":"동생들을 잘 돌보라고 하셨어요","correct":true},{"t":"빈집을 청소하라고 하셨어요","mis":"K2-2-u8-X04"},{"t":"할머니 댁으로 오라고 하셨어요","mis":"K2-2-u8-X04"}],"explanation":["동생 돌보기예요.","249쪽이에요.","첫머리예요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#4','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C8',1,'mc','auto','4월 3일에 미지가 어른이 되었다고 생각한 까닭은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":4,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"4월 3일에 미지가 어른이 되었다고 생각한 까닭은?","options":[{"t":"아홉 살 인생에 첫 택배가 도착했기 때문에","correct":true},{"t":"생일이 지나서","mis":"K2-2-u8-X04"},{"t":"키가 커서","mis":"K2-2-u8-X04"}],"explanation":["첫 택배예요.","256쪽이에요.","미지가 정한 때예요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
