INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#7','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C1',1,'mc','auto','경험을 시나 노래로 표현하면 좋은 점은?',ARRAY['K2-2-u8-X01','K2-2-u8-X02']::text[],false,'{"seq":7,"concept":"K2-2-u8-C1","difficulty":1,"kind":"mc","stem":"경험을 시나 노래로 표현하면 좋은 점은?","options":[{"t":"자신의 경험을 되돌아볼 수 있어요","correct":true},{"t":"경험을 쉽게 잊어버릴 수 있어요","mis":"K2-2-u8-X01"},{"t":"글자를 아주 많이 쓸 수 있어요","mis":"K2-2-u8-X02"}],"explanation":["되돌아봐요.","262쪽이에요.","좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
