INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#9','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C9',2,'mc','auto','금방울의 성격을 근거와 함께 바르게 말한 것은?',ARRAY['K2-2-u8-X12']::text[],false,'{"seq":9,"concept":"K2-2-u8-C9","difficulty":2,"kind":"mc","stem":"금방울의 성격을 근거와 함께 바르게 말한 것은?","options":[{"t":"엄마, 아빠 말씀을 떠올리며 동생들을 찾는 것을 보면 책임감이 강해요","correct":true},{"t":"겁이 없어서 아무에게나 문을 열어 줘요","mis":"K2-2-u8-X12"},{"t":"동생들에게 관심이 없어요","mis":"K2-2-u8-X12"}],"explanation":["책임감이에요.","250쪽이에요.","행동에서요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#10','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C3',2,'match','auto','시에 나온 것과 빗댄 것을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C3","difficulty":2,"kind":"match","stem":"시에 나온 것과 빗댄 것을 이어 보세요.","pairs":[{"l":"눈 밟는 소리","r":"오리 우는 소리"},{"l":"옷을 껴입고 줄지어 걷는 우리","r":"줄지어 걷는 오리들"},{"l":"눈 쌓인 운동장","r":"널따란 호수"}],"mis":"K2-2-u8-X03","explanation":["빗댄 말이에요.","지도서 321쪽이에요.","원래 대상을 찾아요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#11','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C6',2,'mc','auto','줄글과 견준 노랫말의 특징은?',ARRAY['K2-2-u8-X02','K2-2-u8-X07']::text[],false,'{"seq":11,"concept":"K2-2-u8-C6","difficulty":2,"kind":"mc","stem":"줄글과 견준 노랫말의 특징은?","options":[{"t":"경험이나 느낌을 길게 늘여 쓰지 않고 간결하게 표현했어요","correct":true},{"t":"겪은 일을 처음부터 끝까지 다 적었어요","mis":"K2-2-u8-X02"},{"t":"경험과 상관없는 말을 넣었어요","mis":"K2-2-u8-X07"}],"explanation":["간결해요.","241쪽이에요.","줄글과 달라요."],"asset":{"type":"passage","lines":["오늘 친한 친구와 학교에 같이 갔다.","가는 길에 문구점도 보이고 장난감집도 지났다.","날마다 가는 길인데도 친구랑 함께 이야기하면서 가니까","특별하게 느껴졌다."],"title":"『국어』 241쪽 경험을 쓴 줄글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
