INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#19','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C4',3,'ox','auto','같은 눈 오는 날의 경험이라면 누가 써도 똑같은 시가 된다.',ARRAY['K2-2-u8-X05']::text[],false,'{"seq":19,"concept":"K2-2-u8-C4","difficulty":3,"kind":"ox","stem":"같은 눈 오는 날의 경험이라면 누가 써도 똑같은 시가 된다.","answer":"X","reason_options":[{"t":"무엇에 눈길을 두고 표현하느냐에 따라 다른 작품이 되어서","correct":true},{"t":"경험이 같으면 시도 같아야 해서","mis":"K2-2-u8-X05"}],"mis":"K2-2-u8-X05","explanation":["다른 작품이 돼요.","지도서 320쪽이에요.","작가의 관점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#20','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C1',3,'mc','auto','시에 대해 바르게 말한 친구는?',ARRAY['K2-2-u8-X01','K2-2-u8-X02']::text[],false,'{"seq":20,"concept":"K2-2-u8-C1","difficulty":3,"kind":"mc","stem":"시에 대해 바르게 말한 친구는?","options":[{"t":"「시는 겪은 일 가운데 특별한 기분이 든 순간을 골라 알맞은 말로 나타낸 글이야.」","correct":true},{"t":"「시는 그냥 글을 짧게만 쓰면 돼.」","mis":"K2-2-u8-X01"},{"t":"「겪은 일을 길게 다 적으면 시야.」","mis":"K2-2-u8-X02"}],"explanation":["특별한 순간이에요.","지도서 344쪽이에요.","두 오개념을 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#21','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C10',3,'mc','auto','금방울이 여러분과 비슷한 나이라는 것을 생각하면 어울리는 이어질 이야기는?',ARRAY['K2-2-u8-X10']::text[],false,'{"seq":21,"concept":"K2-2-u8-C10","difficulty":3,"kind":"mc","stem":"금방울이 여러분과 비슷한 나이라는 것을 생각하면 어울리는 이어질 이야기는?","options":[{"t":"무서워도 동생을 위해 조심조심 빈집에 가 보는 이야기","correct":true},{"t":"금방울이 덩치를 번쩍 들어 던지는 이야기","mis":"K2-2-u8-X10"},{"t":"금방울이 마법사로 변하는 이야기","mis":"K2-2-u8-X10"}],"explanation":["나이에 맞아요.","지도서 331쪽이에요.","허황되지 않게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#22','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C9',3,'mc','auto','「오, 미지의 택배」에서 미지의 마음을 알 수 있는 부분은?',ARRAY['K2-2-u8-X12']::text[],false,'{"seq":22,"concept":"K2-2-u8-C9","difficulty":3,"kind":"mc","stem":"「오, 미지의 택배」에서 미지의 마음을 알 수 있는 부분은?","options":[{"t":"설명서를 읽고 머릿속이 시끄러워지다가 어느새 운동화를 신고 뛰고 있었던 것","correct":true},{"t":"경비 아저씨가 밥 먹으러 간 것","mis":"K2-2-u8-X12"},{"t":"상자가 파란색인 것","mis":"K2-2-u8-X12"}],"explanation":["설레는 마음이에요.","256쪽이에요.","행동에서요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#23','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C1',4,'sa','auto','경험을 시나 노래로 표현하면 경험한 일을 다른 사람에게 ○○ 나게 전할 수 있어요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u8-C1","difficulty":4,"kind":"sa","stem":"경험을 시나 노래로 표현하면 경험한 일을 다른 사람에게 ○○ 나게 전할 수 있어요. 빈칸 두 글자를 쓰세요.","answer":["실감"],"explanation":["실감이에요.","231쪽이에요.","생생하게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#24','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C3',4,'essay','teacher','지도서 346~347쪽 평가 — 「고양이가 내 뱃속에서」처럼 배가 고팠던 경험을 떠올려, 꼬르륵 소리를 다른 동물에 빗대어 서너 줄 시로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u8-C3","difficulty":4,"kind":"essay","stem":"지도서 346~347쪽 평가 — 「고양이가 내 뱃속에서」처럼 배가 고팠던 경험을 떠올려, 꼬르륵 소리를 다른 동물에 빗대어 서너 줄 시로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 체육 시간 끝나고 / 뱃속에서 강아지가 / 멍멍 꾸르륵 / 어서 밥 달라고 꼬리를 흔든다","scoring_points":["내 경험을 떠올렸어요","다른 동물에 빗대었어요","원래 시의 방식에 맞게 썼어요"]},"explanation":["빗대어 바꿔요.","지도서 346쪽이에요.","경험이 구체적이에요."],"asset":{"type":"scene","icon":"🐱","text":"지도서 347쪽 「고양이가 내 뱃속에서」(권오삼) — 배고파 나는 꼬르륵 소리를 뱃속 고양이가 조르는 것에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_a#25','kor',2,2,'u8','','g2_2_kor_u8_review_a','unit_review','K2-2-u8-C10',4,'essay','teacher','지도서 348~349쪽 평가 — 「오, 미지의 택배」에서 미지가 하늘나라로 가서 만나고 싶은 대상을 정하고, 이어질 이야기를 장면 두세 개로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u8-C10","difficulty":4,"kind":"essay","stem":"지도서 348~349쪽 평가 — 「오, 미지의 택배」에서 미지가 하늘나라로 가서 만나고 싶은 대상을 정하고, 이어질 이야기를 장면 두세 개로 쓰세요.","answer_guide":{"answer":"예: 미지는 눈앞이 노래질 때까지 달려 하늘나라에 닿았다. → 그곳에서 예전에 키우던 강아지를 만나 꼭 안아 주었다. → 30분이 다 되어 가자 미지는 다시 만나러 오겠다며 손을 흔들었다.","scoring_points":["만나고 싶은 대상을 정했어요","흐름에 맞게 장면을 이었어요","미지의 마음이 드러나요"]},"explanation":["흐름과 성격이에요.","지도서 348쪽이에요.","어색해도 까닭을 설명하면 돼요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#1','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C2',1,'mc','auto','「눈 내린 등굣길」에서 쌓인 눈을 밟으면 어떤 소리가 난다고 했나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C2","difficulty":1,"kind":"mc","stem":"「눈 내린 등굣길」에서 쌓인 눈을 밟으면 어떤 소리가 난다고 했나요?","options":[{"t":"오리 우는 소리","correct":true},{"t":"유리창 닦는 소리","mis":"K2-2-u8-X04"},{"t":"북 치는 소리","mis":"K2-2-u8-X04"}],"explanation":["오리 우는 소리예요.","234쪽이에요.","「꽥!」이에요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#2','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C3',1,'mc','auto','「눈 내린 등굣길」에서 눈길을 걷는 아이들을 무엇에 빗대었나요?',ARRAY['K2-2-u8-X03']::text[],false,'{"seq":2,"concept":"K2-2-u8-C3","difficulty":1,"kind":"mc","stem":"「눈 내린 등굣길」에서 눈길을 걷는 아이들을 무엇에 빗대었나요?","options":[{"t":"오리","correct":true},{"t":"고양이","mis":"K2-2-u8-X03"},{"t":"토끼","mis":"K2-2-u8-X03"}],"explanation":["오리예요.","지도서 321쪽이에요.","뒤뚱뒤뚱 걸어요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#3','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C8',1,'mc','auto','금방울이 집에 왔을 때 동생들은 무엇을 하고 있었나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":3,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"금방울이 집에 왔을 때 동생들은 무엇을 하고 있었나요?","options":[{"t":"난롯가에서 몸을 말리고 있었어요","correct":true},{"t":"빈집에서 놀고 있었어요","mis":"K2-2-u8-X04"},{"t":"잠을 자고 있었어요","mis":"K2-2-u8-X04"}],"explanation":["난롯가예요.","249쪽이에요.","마음이 놓였어요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#4','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C8',1,'mc','auto','택배 상자 속에 들어 있던 것은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":4,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"택배 상자 속에 들어 있던 것은?","options":[{"t":"하얀 끈 운동화와 제품 설명서","correct":true},{"t":"반짝이는 장난감 로봇","mis":"K2-2-u8-X04"},{"t":"편지와 사탕","mis":"K2-2-u8-X04"}],"explanation":["운동화와 설명서예요.","254쪽이에요.","심심해 보여요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#5','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C13',1,'mc','auto','「인생」의 뜻은?',ARRAY['K2-2-u8-X15']::text[],false,'{"seq":5,"concept":"K2-2-u8-C13","difficulty":1,"kind":"mc","stem":"「인생」의 뜻은?","options":[{"t":"사람이 세상을 살아가는 일. 또는 그 기간","correct":true},{"t":"재료를 써서 만든 물건","mis":"K2-2-u8-X15"},{"t":"사람이 만들어 내거나 꾸며 낸 것","mis":"K2-2-u8-X15"}],"explanation":["살아가는 일이에요.","257쪽이에요.","아홉 살 인생이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
