INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#7','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C1',1,'mc','auto','경험을 시나 노래로 표현하면 좋은 점은?',ARRAY['K2-2-u8-X01']::text[],false,'{"seq":7,"concept":"K2-2-u8-C1","difficulty":1,"kind":"mc","stem":"경험을 시나 노래로 표현하면 좋은 점은?","options":[{"t":"경험을 다른 사람에게 전할 수 있어요","correct":true},{"t":"경험을 쉽게 잊어버릴 수 있어요","mis":"K2-2-u8-X01"},{"t":"경험이 모두 사라져요","mis":"K2-2-u8-X01"}],"explanation":["전할 수 있어요.","262쪽이에요.","나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#8','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C5',1,'mc','auto','노래 부르기가 부담스러운 친구가 노랫말을 발표할 때 알맞은 것은?',ARRAY['K2-2-u8-X14']::text[],false,'{"seq":8,"concept":"K2-2-u8-C5","difficulty":1,"kind":"mc","stem":"노래 부르기가 부담스러운 친구가 노랫말을 발표할 때 알맞은 것은?","options":[{"t":"노랫말을 또박또박 낭독해도 돼요","correct":true},{"t":"노래를 잘 부를 때까지 발표하면 안 돼요","mis":"K2-2-u8-X14"},{"t":"친구들이 웃으면 그만둬요","mis":"K2-2-u8-X14"}],"explanation":["낭독해도 돼요.","지도서 327쪽이에요.","노랫말이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#9','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C9',2,'mc','auto','낯선 손님이 문을 다시 두드렸을 때 금방울의 마음은?',ARRAY['K2-2-u8-X12']::text[],false,'{"seq":9,"concept":"K2-2-u8-C9","difficulty":2,"kind":"mc","stem":"낯선 손님이 문을 다시 두드렸을 때 금방울의 마음은?","options":[{"t":"가슴이 덩달아 뛸 만큼 무섭고 떨렸어요","correct":true},{"t":"반가워서 문을 열고 싶었어요","mis":"K2-2-u8-X12"},{"t":"아무렇지 않았어요","mis":"K2-2-u8-X12"}],"explanation":["무서웠어요.","249쪽이에요.","빗소리까지요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#10','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C8',2,'match','auto','「빈집에 온 손님」에서 일이 일어난 차례대로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C8","difficulty":2,"kind":"match","stem":"「빈집에 온 손님」에서 일이 일어난 차례대로 이어 보세요.","pairs":[{"l":"첫째","r":"하늘이 어둑해지자 금방울이 동생들을 찾기 시작했다"},{"l":"둘째","r":"금방울이 집에서 동생들을 만났다"},{"l":"셋째","r":"낯선 손님이 문을 두드렸지만 금방울은 문을 열어 주지 않았다"},{"l":"넷째","r":"금방울이 작은방울을 업고 자장가를 불러 주었다"}],"mis":"K2-2-u8-X13","explanation":["차례대로요.","249쪽이에요.","흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
