INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#13','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C10',2,'mc','auto','「빈집에 온 손님」의 이어질 이야기로 가장 알맞은 것은?',ARRAY['K2-2-u8-X10','K2-2-u8-X11']::text[],false,'{"seq":13,"concept":"K2-2-u8-C10","difficulty":2,"kind":"mc","stem":"「빈집에 온 손님」의 이어질 이야기로 가장 알맞은 것은?","options":[{"t":"작은방울이 계속 칭얼대자 금방울은 용기를 내어 담요를 가지러 빈집으로 갔는데, 그곳에 문을 두드렸던 덩치가 있었어요","correct":true},{"t":"갑자기 금방울이 하늘을 날아 우주로 갔어요","mis":"K2-2-u8-X10"},{"t":"덩치가 찾아왔어요. 끝.","mis":"K2-2-u8-X11"}],"explanation":["흐름에 맞아요.","251쪽이에요.","사건이 이어져요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
