INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#15','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C11',2,'mc','auto','친구들의 발표를 들으며 할 일로 알맞은 것은?',ARRAY['K2-2-u8-X09','K2-2-u8-X14']::text[],false,'{"seq":15,"concept":"K2-2-u8-C11","difficulty":2,"kind":"mc","stem":"친구들의 발표를 들으며 할 일로 알맞은 것은?","options":[{"t":"내 이야기와 비슷한 점과 다른 점을 생각하며 들어요","correct":true},{"t":"내 이야기와 다르면 틀렸다고 말해요","mis":"K2-2-u8-X09"},{"t":"그림이 가장 예쁜 이야기만 좋다고 해요","mis":"K2-2-u8-X14"}],"explanation":["견주며 들어요.","지도서 339쪽이에요.","비슷한 점·다른 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
