INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#19','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C7',3,'ox','auto','노랫말을 바꾸어 쓸 때에는 원래 노랫말과 글자 수가 반드시 똑같아야 한다.',ARRAY['K2-2-u8-X06']::text[],false,'{"seq":19,"concept":"K2-2-u8-C7","difficulty":3,"kind":"ox","stem":"노랫말을 바꾸어 쓸 때에는 원래 노랫말과 글자 수가 반드시 똑같아야 한다.","answer":"X","reason_options":[{"t":"노랫말 창작이 목적이라 글자 수에 매이지 않고 자유롭게 낱말을 고를 수 있어서","correct":true},{"t":"글자 수가 다르면 틀린 노랫말이라서","mis":"K2-2-u8-X06"}],"mis":"K2-2-u8-X06","explanation":["자유롭게요.","지도서 327쪽이에요.","창작이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#20','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C6',3,'mc','auto','줄글로 된 경험을 노랫말로 바꾸면 어떤 점이 달라지나요?',ARRAY['K2-2-u8-X02','K2-2-u8-X07']::text[],false,'{"seq":20,"concept":"K2-2-u8-C6","difficulty":3,"kind":"mc","stem":"줄글로 된 경험을 노랫말로 바꾸면 어떤 점이 달라지나요?","options":[{"t":"꼭 필요한 낱말만 골라 짧고 리듬 있게 나타내요","correct":true},{"t":"더 길고 자세해져요","mis":"K2-2-u8-X02"},{"t":"경험이 모두 빠져요","mis":"K2-2-u8-X07"}],"explanation":["간결하고 리듬 있게요.","241쪽이에요.","중요한 낱말이에요."],"asset":{"type":"passage","lines":["오늘 친한 친구와 학교에 같이 갔다.","가는 길에 문구점도 보이고 장난감집도 지났다.","날마다 가는 길인데도 친구랑 함께 이야기하면서 가니까","특별하게 느껴졌다."],"title":"『국어』 241쪽 경험을 쓴 줄글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#21','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C10',3,'mc','auto','꾸민 이야기를 장면으로 나눌 때 기준으로 알맞은 것은?',ARRAY['K2-2-u8-X11']::text[],false,'{"seq":21,"concept":"K2-2-u8-C10","difficulty":3,"kind":"mc","stem":"꾸민 이야기를 장면으로 나눌 때 기준으로 알맞은 것은?","options":[{"t":"인물의 마음이 바뀌거나, 다른 행동을 하거나, 다른 인물이 나올 때","correct":true},{"t":"글자 수가 열 개가 될 때마다","mis":"K2-2-u8-X11"},{"t":"아무 데서나","mis":"K2-2-u8-X11"}],"explanation":["장면 나누기예요.","지도서 339쪽이에요.","세 가지 잣대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#22','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C3',3,'mc','auto','눈 밟는 소리를 새롭게 빗대어 표현한 것은?',ARRAY['K2-2-u8-X01','K2-2-u8-X02']::text[],false,'{"seq":22,"concept":"K2-2-u8-C3","difficulty":3,"kind":"mc","stem":"눈 밟는 소리를 새롭게 빗대어 표현한 것은?","options":[{"t":"「뽀드득 눈을 밟으면 유리창을 닦는 소리처럼 들린다.」","correct":true},{"t":"「눈을 밟았다.」","mis":"K2-2-u8-X01"},{"t":"「눈이 왔다. 추웠다. 집에 갔다.」","mis":"K2-2-u8-X02"}],"explanation":["흉내 내고 빗댔어요.","235쪽이에요.","생생해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#23','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C8',4,'sa','auto','금방울이 작은방울을 업고 불러 준 노래는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u8-C8","difficulty":4,"kind":"sa","stem":"금방울이 작은방울을 업고 불러 준 노래는 무엇인가요? 세 글자로 쓰세요.","answer":["자장가"],"explanation":["자장가예요.","249쪽이에요.","잠을 재워요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#24','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C3',4,'essay','teacher','눈을 밟았던 경험을 떠올려 눈 밟는 소리나 모습을 무엇에 빗대어 재미있게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u8-C3","difficulty":4,"kind":"essay","stem":"눈을 밟았던 경험을 떠올려 눈 밟는 소리나 모습을 무엇에 빗대어 재미있게 쓰세요.","answer_guide":{"answer":"예: 빠드득빠드득 눈을 밟으면 과자를 씹는 소리가 들린다.","scoring_points":["소리나 모습을 흉내 냈어요","무엇에 빗대었어요"]},"explanation":["빗대어 써요.","235쪽이에요.","내 경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_b#25','kor',2,2,'u8','','g2_2_kor_u8_review_b','unit_review','K2-2-u8-C10',4,'essay','teacher','「빈집에 온 손님」에서 금방울이 문틈으로 어둠만 본 뒤에 이어질 이야기를 두 장면으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u8-C10","difficulty":4,"kind":"essay","stem":"「빈집에 온 손님」에서 금방울이 문틈으로 어둠만 본 뒤에 이어질 이야기를 두 장면으로 쓰세요.","answer_guide":{"answer":"예: 작은방울이 계속 칭얼대자 금방울은 담요를 가지러 빈집으로 갔다. → 빈집 안에는 비에 젖은 덩치가 담요를 덮고 떨고 있었고, 금방울은 깜짝 놀라 뒷걸음질 쳤다.","scoring_points":["흐름에 맞게 이어졌어요","두 장면으로 나누었어요","인물의 성격에 어울려요"]},"explanation":["두 장면이에요.","250쪽이에요.","사건을 이어요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#1','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C2',1,'mc','auto','「눈 내린 등굣길」에 담긴 경험은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C2","difficulty":1,"kind":"mc","stem":"「눈 내린 등굣길」에 담긴 경험은?","options":[{"t":"눈 쌓인 날 친구들과 함께 학교에 걸어간 일","correct":true},{"t":"여름에 바닷가에서 논 일","mis":"K2-2-u8-X04"},{"t":"집에서 눈사람 그림을 그린 일","mis":"K2-2-u8-X04"}],"explanation":["등굣길이에요.","지도서 321쪽이에요.","눈길을 걸어요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#2','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C3',1,'mc','auto','231쪽 말풍선에서 우리 반 쉬는 시간을 무엇에 빗대었나요?',ARRAY['K2-2-u8-X03']::text[],false,'{"seq":2,"concept":"K2-2-u8-C3","difficulty":1,"kind":"mc","stem":"231쪽 말풍선에서 우리 반 쉬는 시간을 무엇에 빗대었나요?","options":[{"t":"놀이공원","correct":true},{"t":"도서관","mis":"K2-2-u8-X03"},{"t":"병원","mis":"K2-2-u8-X03"}],"explanation":["놀이공원이에요.","231쪽이에요.","다양한 놀이를 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#3','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C8',1,'mc','auto','문틈으로 커다란 덩치를 본 금방울은 어떻게 했나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":3,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"문틈으로 커다란 덩치를 본 금방울은 어떻게 했나요?","options":[{"t":"문을 열지 않고 살그머니 문고리를 걸었어요","correct":true},{"t":"문을 활짝 열어 주었어요","mis":"K2-2-u8-X04"},{"t":"밖으로 뛰쳐나갔어요","mis":"K2-2-u8-X04"}],"explanation":["문고리를 걸었어요.","247쪽이에요.","말씀을 지켜요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#4','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C8',1,'mc','auto','택배 상자 속 운동화가 특별한 점은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":4,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"택배 상자 속 운동화가 특별한 점은?","options":[{"t":"하늘나라에 있는 누군가에게 데려다줘요","correct":true},{"t":"신으면 하늘을 날아다녀요","mis":"K2-2-u8-X04"},{"t":"신으면 키가 커져요","mis":"K2-2-u8-X04"}],"explanation":["데려다줘요.","256쪽이에요.","설명서예요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#5','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C13',1,'mc','auto','「제품」의 뜻은?',ARRAY['K2-2-u8-X15']::text[],false,'{"seq":5,"concept":"K2-2-u8-C13","difficulty":1,"kind":"mc","stem":"「제품」의 뜻은?","options":[{"t":"재료를 써서 만든 물건. 또는 그렇게 만드는 일","correct":true},{"t":"사람이 세상을 살아가는 일","mis":"K2-2-u8-X15"},{"t":"사람이 만들어 내거나 꾸며 낸 것","mis":"K2-2-u8-X15"}],"explanation":["만든 물건이에요.","257쪽이에요.","제품 설명서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#6','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C13',1,'mc','auto','「너울」의 뜻은?',ARRAY['K2-2-u8-X15']::text[],false,'{"seq":6,"concept":"K2-2-u8-C13","difficulty":1,"kind":"mc","stem":"「너울」의 뜻은?","options":[{"t":"바다의 크고 사나운 물결","correct":true},{"t":"은하수를 이르는 말","mis":"K2-2-u8-X15"},{"t":"많고 많은 것 가운데 가장 뛰어난 것","mis":"K2-2-u8-X15"}],"explanation":["큰 물결이에요.","264쪽이에요.","토박이말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#7','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C1',1,'mc','auto','262쪽 1번 — 경험을 시나 노래로 표현하면 좋은 점이 아닌 것은?',ARRAY['K2-2-u8-X01']::text[],false,'{"seq":7,"concept":"K2-2-u8-C1","difficulty":1,"kind":"mc","stem":"262쪽 1번 — 경험을 시나 노래로 표현하면 좋은 점이 아닌 것은?","options":[{"t":"경험을 쉽게 잊어버릴 수 있다","correct":true},{"t":"자신의 경험을 되돌아볼 수 있다","mis":"K2-2-u8-X01"},{"t":"경험을 다른 사람에게 전할 수 있다","mis":"K2-2-u8-X01"}],"explanation":["잊는 게 아니에요.","262쪽이에요.","○표 아닌 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#8','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C5',1,'mc','auto','친구가 시를 낭송하는 것을 들을 때 알맞은 것은?',ARRAY['K2-2-u8-X14']::text[],false,'{"seq":8,"concept":"K2-2-u8-C5","difficulty":1,"kind":"mc","stem":"친구가 시를 낭송하는 것을 들을 때 알맞은 것은?","options":[{"t":"장면을 떠올리며 듣고 어떤 느낌이 드는지 말해요","correct":true},{"t":"옆 친구와 떠들어요","mis":"K2-2-u8-X14"},{"t":"틀린 곳만 찾아 놀려요","mis":"K2-2-u8-X14"}],"explanation":["느낌을 말해요.","지도서 323쪽이에요.","바른 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#9','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C9',2,'mc','auto','인물의 성격을 이야기할 때 알맞은 방법은?',ARRAY['K2-2-u8-X12']::text[],false,'{"seq":9,"concept":"K2-2-u8-C9","difficulty":2,"kind":"mc","stem":"인물의 성격을 이야기할 때 알맞은 방법은?","options":[{"t":"이야기 속 어느 말이나 행동에서 그렇게 느꼈는지 찾아 까닭과 함께 말해요","correct":true},{"t":"그냥 느낌만 말해요","mis":"K2-2-u8-X12"},{"t":"그림 색깔만 보고 말해요","mis":"K2-2-u8-X12"}],"explanation":["근거를 찾아요.","지도서 330쪽이에요.","작품 속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#10','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C8',2,'match','auto','「오, 미지의 택배」에서 일이 일어난 차례대로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C8","difficulty":2,"kind":"match","stem":"「오, 미지의 택배」에서 일이 일어난 차례대로 이어 보세요.","pairs":[{"l":"첫째","r":"미지에게 택배가 도착했다"},{"l":"둘째","r":"미지는 경비실에서 파란색 택배 상자를 찾아왔다"},{"l":"셋째","r":"택배 상자 안에 운동화가 들어 있었다"},{"l":"넷째","r":"미지는 제품 설명서를 발견하고 읽었다"},{"l":"다섯째","r":"미지는 운동화를 신고 폴짝폴짝 세 번 뛰었다"}],"mis":"K2-2-u8-X13","explanation":["차례대로요.","257쪽이에요.","흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#11','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C6',2,'mc','auto','「문구점」과 「장난감집」이 노랫말에 고른 낱말이 된 까닭은?',ARRAY['K2-2-u8-X01','K2-2-u8-X07']::text[],false,'{"seq":11,"concept":"K2-2-u8-C6","difficulty":2,"kind":"mc","stem":"「문구점」과 「장난감집」이 노랫말에 고른 낱말이 된 까닭은?","options":[{"t":"친구와 함께 걸으며 본, 그날 경험에서 중요한 곳이라서","correct":true},{"t":"가장 짧은 낱말이라서","mis":"K2-2-u8-X01"},{"t":"아무 낱말이나 넣어서","mis":"K2-2-u8-X07"}],"explanation":["중요한 곳이에요.","지도서 326쪽이에요.","정서를 불러와요."],"asset":{"type":"passage","lines":["오늘 친한 친구와 학교에 같이 갔다.","가는 길에 문구점도 보이고 장난감집도 지났다.","날마다 가는 길인데도 친구랑 함께 이야기하면서 가니까","특별하게 느껴졌다."],"title":"『국어』 241쪽 경험을 쓴 줄글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#12','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C7',2,'mc','auto','할아버지와 산책했던 경험으로 노랫말을 바꿀 때 가장 알맞은 것은?',ARRAY['K2-2-u8-X07']::text[],false,'{"seq":12,"concept":"K2-2-u8-C7","difficulty":2,"kind":"mc","stem":"할아버지와 산책했던 경험으로 노랫말을 바꿀 때 가장 알맞은 것은?","options":[{"t":"산책하며 지나간 곳, 「할아버지랑」, 그때 느낌으로 바꾸어 써요","correct":true},{"t":"친구 이름을 그대로 두고 장소만 바꿔요","mis":"K2-2-u8-X07"},{"t":"노랫말을 하나도 바꾸지 않아요","mis":"K2-2-u8-X07"}],"explanation":["경험에 맞게요.","242쪽이에요.","누구와를 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#13','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C10',2,'mc','auto','미지가 하늘나라에 닿았다면, 이어서 미지가 할 행동으로 알맞은 것은?',ARRAY['K2-2-u8-X10','K2-2-u8-X13']::text[],false,'{"seq":13,"concept":"K2-2-u8-C10","difficulty":2,"kind":"mc","stem":"미지가 하늘나라에 닿았다면, 이어서 미지가 할 행동으로 알맞은 것은?","options":[{"t":"보고 싶었던 누군가를 찾아 두리번거려요","correct":true},{"t":"택배 상자를 버리고 잠을 자요","mis":"K2-2-u8-X10"},{"t":"운동화를 본 적이 없다고 해요","mis":"K2-2-u8-X13"}],"explanation":["마음에 이어져요.","지도서 339쪽이에요.","흐름에 맞아요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#14','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C4',2,'mc','auto','「눈 온 아침」에서 눈 위에 나란히 난 발자국을 보고 떠올린 생각은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":14,"concept":"K2-2-u8-C4","difficulty":2,"kind":"mc","stem":"「눈 온 아침」에서 눈 위에 나란히 난 발자국을 보고 떠올린 생각은?","options":[{"t":"이른 아침 누가 어디로 갔는지 궁금했어요","correct":true},{"t":"발자국이 지저분하다고 생각했어요","mis":"K2-2-u8-X04"},{"t":"눈이 빨리 녹기를 바랐어요","mis":"K2-2-u8-X04"}],"explanation":["궁금했어요.","236쪽이에요.","발자국의 주인이에요."],"asset":{"type":"scene","icon":"🎵","text":"『국어』 236쪽 노래 「눈 온 아침」 — 눈 내린 들길의 발자국을 보고 누가 어디로 갔는지 궁금해하는 노래예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#15','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C11',2,'mc','auto','상상한 이어질 이야기를 발표할 때 알맞은 것은?',ARRAY['K2-2-u8-X09','K2-2-u8-X14']::text[],false,'{"seq":15,"concept":"K2-2-u8-C11","difficulty":2,"kind":"mc","stem":"상상한 이어질 이야기를 발표할 때 알맞은 것은?","options":[{"t":"장면 차례대로 또박또박 말하고 왜 그렇게 상상했는지도 말해요","correct":true},{"t":"친구 이야기를 그대로 따라 해요","mis":"K2-2-u8-X09"},{"t":"작게 중얼거려요","mis":"K2-2-u8-X14"}],"explanation":["까닭도 말해요.","259쪽이에요.","바른 자세예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
