INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#19','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C10',3,'ox','auto','이어질 이야기는 원래 작가가 쓴 이야기와 똑같아야 좋은 이야기다.',ARRAY['K2-2-u8-X09']::text[],false,'{"seq":19,"concept":"K2-2-u8-C10","difficulty":3,"kind":"ox","stem":"이어질 이야기는 원래 작가가 쓴 이야기와 똑같아야 좋은 이야기다.","answer":"X","reason_options":[{"t":"흐름과 인물의 성격에 맞는다면 사람마다 다르게 이어질 수 있어서","correct":true},{"t":"작가가 쓴 것만 정답이라서","mis":"K2-2-u8-X09"}],"mis":"K2-2-u8-X09","explanation":["다르게 이어져도 돼요.","지도서 317쪽이에요.","원작은 하나의 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
