INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#21','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C10',3,'mc','auto','잘 알려진 이야기 「토끼와 거북」의 이어질 이야기로 흐름에 알맞은 것은?',ARRAY['K2-2-u8-X10','K2-2-u8-X09']::text[],false,'{"seq":21,"concept":"K2-2-u8-C10","difficulty":3,"kind":"mc","stem":"잘 알려진 이야기 「토끼와 거북」의 이어질 이야기로 흐름에 알맞은 것은?","options":[{"t":"경주에서 진 토끼가 다시 겨루자며 거북을 찾아가는 이야기","correct":true},{"t":"토끼와 거북이 갑자기 우주 전쟁을 하는 이야기","mis":"K2-2-u8-X10"},{"t":"「토끼와 거북」과 똑같이 다시 쓴 이야기","mis":"K2-2-u8-X09"}],"explanation":["흐름에 맞아요.","지도서 341쪽이에요.","뒷이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#22','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C12',3,'mc','auto','그림책을 만들 때 이야기를 여러 장면으로 나누는 까닭은?',ARRAY['K2-2-u8-X14','K2-2-u8-X01']::text[],false,'{"seq":22,"concept":"K2-2-u8-C12","difficulty":3,"kind":"mc","stem":"그림책을 만들 때 이야기를 여러 장면으로 나누는 까닭은?","options":[{"t":"이야기의 흐름을 그림과 글로 차례차례 보여 주려고","correct":true},{"t":"그림을 많이 그리려고","mis":"K2-2-u8-X14"},{"t":"글자를 줄이려고","mis":"K2-2-u8-X01"}],"explanation":["흐름을 보여 줘요.","지도서 341쪽이에요.","한 면에 한 장면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#23','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C13',4,'sa','auto','여러 사람이 크지 않은 목소리로 정답게 이야기하는 소리나 모양을 나타내는 네 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u8-C13","difficulty":4,"kind":"sa","stem":"여러 사람이 크지 않은 목소리로 정답게 이야기하는 소리나 모양을 나타내는 네 글자 낱말을 쓰세요.","answer":["도란도란"],"explanation":["도란도란이에요.","240쪽이에요.","노랫말 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#24','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C7',4,'essay','teacher','반가운 사람과 함께 걸었던 일을 떠올려 「지나간 곳 두 군데 · 가는 곳 · 함께 간 사람 · 그때 느낌」을 넣어 노랫말 한 줄을 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u8-C7","difficulty":4,"kind":"essay","stem":"반가운 사람과 함께 걸었던 일을 떠올려 「지나간 곳 두 군데 · 가는 곳 · 함께 간 사람 · 그때 느낌」을 넣어 노랫말 한 줄을 바꾸어 쓰세요.","answer_guide":{"answer":"예: 놀이터를 지나고 빵집 지나서 / 도서관 가는 길 언니랑 함께 가서 설레는 길","scoring_points":["지나간 곳과 가는 곳이 있어요","함께 간 사람과 느낌이 있어요"]},"explanation":["내 경험을 담아요.","243쪽이에요.","글자 수는 자유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_c#25','kor',2,2,'u8','','g2_2_kor_u8_review_c','unit_review','K2-2-u8-C9',4,'essay','teacher','「빈집에 온 손님」에 나온 인물 한 명을 골라 성격을 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u8-C9","difficulty":4,"kind":"essay","stem":"「빈집에 온 손님」에 나온 인물 한 명을 골라 성격을 쓰고, 그렇게 생각한 까닭을 이야기에서 찾아 쓰세요.","answer_guide":{"answer":"예: 금방울은 책임감이 강하다. 비가 쏟아지는데도 엄마 아빠 말씀을 떠올리며 동생들을 찾아다녔기 때문이다.","scoring_points":["인물의 성격을 썼어요","이야기에서 근거를 찾았어요"]},"explanation":["근거와 함께요.","250쪽이에요.","작품 속에서요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#1','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C2',1,'mc','auto','「함께 걸어 좋은 길」에서 「나」는 「너」와 함께 어디로 가고 오나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":1,"concept":"K2-2-u8-C2","difficulty":1,"kind":"mc","stem":"「함께 걸어 좋은 길」에서 「나」는 「너」와 함께 어디로 가고 오나요?","options":[{"t":"학교","correct":true},{"t":"시장","mis":"K2-2-u8-X04"},{"t":"바다","mis":"K2-2-u8-X04"}],"explanation":["학교예요.","240쪽이에요.","가고 오는 길이에요."],"asset":{"type":"scene","icon":"🎶","text":"『국어』 239쪽 노래 「함께 걸어 좋은 길」 — 친구와 함께 문구점·장난감집을 지나 학교에 가고 오는 길이 좋다는 노래예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#2','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C3',1,'mc','auto','「고양이가 내 뱃속에서」에서 배고플 때 나는 꼬르륵 소리를 무엇에 빗대었나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":2,"concept":"K2-2-u8-C3","difficulty":1,"kind":"mc","stem":"「고양이가 내 뱃속에서」에서 배고플 때 나는 꼬르륵 소리를 무엇에 빗대었나요?","options":[{"t":"뱃속 고양이가 급식 먹자고 조르는 소리","correct":true},{"t":"비 오는 소리","mis":"K2-2-u8-X04"},{"t":"자동차 소리","mis":"K2-2-u8-X04"}],"explanation":["고양이예요.","지도서 347쪽이에요.","빗댄 말이에요."],"asset":{"type":"scene","icon":"🐱","text":"지도서 347쪽 「고양이가 내 뱃속에서」(권오삼) — 배고파 나는 꼬르륵 소리를 뱃속 고양이가 조르는 것에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#3','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C8',1,'mc','auto','작은방울이 잠들 때 꼭 필요한 것은?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":3,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"작은방울이 잠들 때 꼭 필요한 것은?","options":[{"t":"만지작거릴 담요","correct":true},{"t":"인형","mis":"K2-2-u8-X04"},{"t":"베개","mis":"K2-2-u8-X04"}],"explanation":["담요예요.","248쪽이에요.","빈집에 두고 왔어요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#4','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C8',1,'mc','auto','미지가 경비실에서 받아 온 택배 상자는 무슨 색이었나요?',ARRAY['K2-2-u8-X04']::text[],false,'{"seq":4,"concept":"K2-2-u8-C8","difficulty":1,"kind":"mc","stem":"미지가 경비실에서 받아 온 택배 상자는 무슨 색이었나요?","options":[{"t":"파란색","correct":true},{"t":"빨간색","mis":"K2-2-u8-X04"},{"t":"노란색","mis":"K2-2-u8-X04"}],"explanation":["파란색이에요.","253쪽이에요.","파란 상자예요."],"asset":{"type":"passage","lines":["아홉 살 미지는 자기 앞으로 온 택배를 받으면 어른이라고 정해 두었어요.","경비 아저씨가 「오미지」라고 찍힌 파란 택배 상자를 주셨어요.","상자 안에는 하얀 끈 운동화와 제품 설명서가 있었어요.","설명서: 하늘나라로 떠난 누군가에게 데려다주는 운동화.","이름을 세 번 부르며 세 번 뛰고 힘껏 달릴 것. 머무는 시간은 30분.","정신을 차려 보니 미지는 벌써 운동화를 신고 세 번 뛰고 있었어요."],"title":"『국어』 252~256쪽 「오, 미지의 택배」(차영아) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#5','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C13',1,'mc','auto','「인공」의 뜻은?',ARRAY['K2-2-u8-X15']::text[],false,'{"seq":5,"concept":"K2-2-u8-C13","difficulty":1,"kind":"mc","stem":"「인공」의 뜻은?","options":[{"t":"사람이 만들어 내거나 꾸며 낸 것","correct":true},{"t":"사람이 세상을 살아가는 일","mis":"K2-2-u8-X15"},{"t":"재료를 써서 만든 물건","mis":"K2-2-u8-X15"}],"explanation":["사람이 만든 것이에요.","257쪽이에요.","인공 지능이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
