INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#7','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C1',1,'mc','auto','경험을 노래로 만들어 불러 보면 좋은 점은?',ARRAY['K2-2-u8-X01','K2-2-u8-X07']::text[],false,'{"seq":7,"concept":"K2-2-u8-C1","difficulty":1,"kind":"mc","stem":"경험을 노래로 만들어 불러 보면 좋은 점은?","options":[{"t":"경험에서 느꼈던 기분을 잘 표현할 수 있어요","correct":true},{"t":"노래로 부르면 경험이 사라져요","mis":"K2-2-u8-X01"},{"t":"노래는 경험과 상관없어요","mis":"K2-2-u8-X07"}],"explanation":["기분을 나타내요.","231쪽이에요.","노래도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#8','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C5',1,'mc','auto','「눈 내린 등굣길」 장면을 몸으로 표현할 때 알맞은 것은?',ARRAY['K2-2-u8-X04','K2-2-u8-X14']::text[],false,'{"seq":8,"concept":"K2-2-u8-C5","difficulty":1,"kind":"mc","stem":"「눈 내린 등굣길」 장면을 몸으로 표현할 때 알맞은 것은?","options":[{"t":"줄지어 서서 눈을 밟듯 뒤뚱뒤뚱 걸어요","correct":true},{"t":"마음대로 뛰어다녀요","mis":"K2-2-u8-X04"},{"t":"가만히 앉아 있어요","mis":"K2-2-u8-X14"}],"explanation":["줄지어 걸어요.","234쪽이에요.","시의 경험이에요."],"asset":{"type":"scene","icon":"🦆","text":"『국어』 232~233쪽 「눈 내린 등굣길」(곽해룡) — 눈길을 걸어 등교하는 아이들을 오리에 빗댄 시예요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#9','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C9',2,'mc','auto','금방울이 문을 열지 않고 문고리를 건 까닭은?',ARRAY['K2-2-u8-X04','K2-2-u8-X12']::text[],false,'{"seq":9,"concept":"K2-2-u8-C9","difficulty":2,"kind":"mc","stem":"금방울이 문을 열지 않고 문고리를 건 까닭은?","options":[{"t":"낯선 손님에게 함부로 문을 열지 말라는 말씀을 지키려고","correct":true},{"t":"문고리가 고장 나서","mis":"K2-2-u8-X04"},{"t":"덩치를 놀리려고","mis":"K2-2-u8-X12"}],"explanation":["말씀을 지켰어요.","247쪽이에요.","동생을 지켜요."],"asset":{"type":"passage","lines":["엄마 아빠는 동생들을 잘 돌보고 낯선 손님에게 문을 열지 말라고 하셨어요.","비가 쏟아지자 금방울은 사라진 동생들을 찾아 달렸어요.","동생들은 집 난롯가에서 젖은 몸을 말리고 있었어요.","그때 커다란 덩치가 문을 쿵쿵 두드렸어요.","금방울은 문을 열지 않고 살그머니 문고리를 걸었어요.","작은방울은 담요를 만지작거려야 잠이 드는데, 담요는 빈집에 있었어요.","금방울은 작은방울을 업고 자장가를 불렀어요.","다시 문틈으로 보니 덩치는 없고 어둠뿐이었어요."],"title":"『국어』 244~248쪽 「빈집에 온 손님」(황선미) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#10','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C13',2,'match','auto','토박이말과 뜻을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u8-C13","difficulty":2,"kind":"match","stem":"토박이말과 뜻을 이어 보세요.","pairs":[{"l":"미리내","r":"은하수를 이르는 말"},{"l":"으뜸","r":"많고 많은 것 가운데 가장 뛰어난 것"},{"l":"너울","r":"바다의 크고 사나운 물결"},{"l":"갈무리","r":"물건 따위를 잘 정리하거나 간수함"}],"mis":"K2-2-u8-X15","explanation":["토박이말이에요.","264쪽이에요.","뜻을 이어요."],"asset":{"type":"passage","lines":["밤하늘에 보이는 미리내는 정말 아름답다.","현지는 우리 반에서 친구를 돕는 마음이 으뜸이다.","바다에 너울이 일고 있다.","선물로 받은 장난감을 잘 갈무리해야겠다."],"title":"『국어』 264쪽 기초 다지기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#11','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C6',2,'mc','auto','241쪽 도움말 — 노랫말을 쓸 때 알맞은 것은?',ARRAY['K2-2-u8-X02','K2-2-u8-X07']::text[],false,'{"seq":11,"concept":"K2-2-u8-C6","difficulty":2,"kind":"mc","stem":"241쪽 도움말 — 노랫말을 쓸 때 알맞은 것은?","options":[{"t":"글자 수를 맞추거나 비슷한 표현을 반복해 노래의 흐름에 어울리게 써요","correct":true},{"t":"겪은 일을 길게 다 적어요","mis":"K2-2-u8-X02"},{"t":"노래와 상관없는 말을 넣어요","mis":"K2-2-u8-X07"}],"explanation":["흐름에 어울리게요.","241쪽이에요.","반복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#12','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C7',2,'mc','auto','노랫말 바꾸어 쓰기가 어려운 친구에게 알맞은 도움은?',ARRAY['K2-2-u8-X07','K2-2-u8-X06']::text[],false,'{"seq":12,"concept":"K2-2-u8-C7","difficulty":2,"kind":"mc","stem":"노랫말 바꾸어 쓰기가 어려운 친구에게 알맞은 도움은?","options":[{"t":"지나온 장소 같은 일부만 바꾸어 써 보게 해요","correct":true},{"t":"바꾸지 말고 그대로 옮겨 쓰게 해요","mis":"K2-2-u8-X07"},{"t":"글자 수를 똑같이 맞출 때까지 다시 쓰게 해요","mis":"K2-2-u8-X06"}],"explanation":["일부만 바꿔도 돼요.","지도서 327쪽이에요.","창작의 즐거움이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#13','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C10',2,'mc','auto','『국어활동』 106쪽 — 「밤에도 놀면 안 돼?」에 이어질 이야기를 흐름에 알맞게 말한 친구는?',ARRAY['K2-2-u8-X10']::text[],false,'{"seq":13,"concept":"K2-2-u8-C10","difficulty":2,"kind":"mc","stem":"『국어활동』 106쪽 — 「밤에도 놀면 안 돼?」에 이어질 이야기를 흐름에 알맞게 말한 친구는?","options":[{"t":"「태양이와 깜깜이는 몸이 서로 바뀌어서 소원이 이루어졌어요.」","correct":true},{"t":"「태양이와 깜깜이는 신나서 밖으로 놀러 나갔어요.」","mis":"K2-2-u8-X10"},{"t":"「달님이 태양이의 소원을 들어주지 않고 밤에 푹 자라고 했어요.」","mis":"K2-2-u8-X10"}],"explanation":["소원이 이루어져요.","국어활동 106쪽 예시 답안이에요.","흐름에 맞아요."],"asset":{"type":"passage","lines":["태양이는 밤에도 계속 놀고 싶은 어린이예요.","깜깜이는 밤에도 계속 자고 싶은 박쥐예요.","달이 유난히 밝은 밤, 둘은 저마다 소원을 빌었어요.","그러자 아주 놀라운 일이 일어났어요."],"title":"『국어활동』 104~105쪽 「밤에도 놀면 안 돼?」(이주혜) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
