INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#15','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C11',2,'mc','auto','친구 이야기에 대한 느낌을 알맞게 말한 것은?',ARRAY['K2-2-u8-X09','K2-2-u8-X12']::text[],false,'{"seq":15,"concept":"K2-2-u8-C11","difficulty":2,"kind":"mc","stem":"친구 이야기에 대한 느낌을 알맞게 말한 것은?","options":[{"t":"「나는 덩치를 호랑이로 상상했는데 너는 아픈 오소리로 상상해서 마음이 따뜻해졌어.」","correct":true},{"t":"「내 이야기가 더 좋아.」","mis":"K2-2-u8-X09"},{"t":"「그냥 별로야.」","mis":"K2-2-u8-X12"}],"explanation":["견주어 말해요.","251쪽이에요.","생각이나 느낌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
