INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#19','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C10',3,'ox','auto','이어질 이야기가 조금 특이하게 흘러가도 이야기의 흐름과 인물의 성격으로 그 까닭을 설명할 수 있으면 좋은 이야기다.',ARRAY['K2-2-u8-X10']::text[],false,'{"seq":19,"concept":"K2-2-u8-C10","difficulty":3,"kind":"ox","stem":"이어질 이야기가 조금 특이하게 흘러가도 이야기의 흐름과 인물의 성격으로 그 까닭을 설명할 수 있으면 좋은 이야기다.","answer":"O","reason_options":[{"t":"흐름과 성격을 생각해 상상했다는 뜻이라서","correct":true},{"t":"특이하면 무조건 좋아서","mis":"K2-2-u8-X10"}],"mis":"K2-2-u8-X10","explanation":["까닭을 설명해요.","지도서 317쪽이에요.","타당성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#20','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C7',3,'mc','auto','262쪽 2번 — 시나 노래를 바꾸어 쓰는 방법으로 알맞지 않은 것은?',ARRAY['K2-2-u8-X07']::text[],false,'{"seq":20,"concept":"K2-2-u8-C7","difficulty":3,"kind":"mc","stem":"262쪽 2번 — 시나 노래를 바꾸어 쓰는 방법으로 알맞지 않은 것은?","options":[{"t":"원래 노래와 상관없이 자신이 가장 좋아하는 말로 바꾸어 쓴다","correct":true},{"t":"노래와 관련한 자신의 경험을 떠올리며 바꾸어 쓸 내용을 생각한다","mis":"K2-2-u8-X07"},{"t":"경험한 일을 간결하게 노래하듯이 표현한다","mis":"K2-2-u8-X07"}],"explanation":["상관없는 말이 아니에요.","262쪽이에요.","알맞지 않은 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#21','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C10',3,'mc','auto','263쪽 3번 — 이어질 이야기를 상상하는 방법으로 알맞은 것은?',ARRAY['K2-2-u8-X10','K2-2-u8-X09']::text[],false,'{"seq":21,"concept":"K2-2-u8-C10","difficulty":3,"kind":"mc","stem":"263쪽 3번 — 이어질 이야기를 상상하는 방법으로 알맞은 것은?","options":[{"t":"인물이 어떤 행동을 했는지 생각해야 한다","correct":true},{"t":"인물과 상관없이 기발하고 재미있으면 된다","mis":"K2-2-u8-X10"},{"t":"원래 이야기와 비슷할수록 좋다","mis":"K2-2-u8-X09"}],"explanation":["인물의 행동이에요.","263쪽이에요.","길 찾기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#22','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C13',3,'mc','auto','토박이말을 뜻에 맞게 넣은 문장은?',ARRAY['K2-2-u8-X15']::text[],false,'{"seq":22,"concept":"K2-2-u8-C13","difficulty":3,"kind":"mc","stem":"토박이말을 뜻에 맞게 넣은 문장은?","options":[{"t":"「다 쓴 색연필을 상자에 잘 갈무리했다.」","correct":true},{"t":"「바다에 미리내가 높게 일었다.」","mis":"K2-2-u8-X15"},{"t":"「밤하늘에 너울이 반짝인다.」","mis":"K2-2-u8-X15"}],"explanation":["갈무리예요.","264쪽이에요.","자리에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#23','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C13',4,'sa','auto','은하수를 이르는 토박이말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u8-C13","difficulty":4,"kind":"sa","stem":"은하수를 이르는 토박이말을 세 글자로 쓰세요.","answer":["미리내"],"explanation":["미리내예요.","264쪽이에요.","토박이말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#24','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C1',4,'essay','teacher','어떤 경험을 시나 이야기로 표현하고 싶은지 「언제 / 무엇을 / 어떤 기분」을 넣어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u8-C1","difficulty":4,"kind":"essay","stem":"어떤 경험을 시나 이야기로 표현하고 싶은지 「언제 / 무엇을 / 어떤 기분」을 넣어 쓰세요.","answer_guide":{"answer":"예: 지난 겨울에 친구들과 눈썰매를 탔을 때 바람을 가르며 내려와 정말 신났던 경험을 시로 쓰고 싶다.","scoring_points":["언제·무엇을 했는지 썼어요","그때 기분을 썼어요"]},"explanation":["경험과 기분이에요.","229쪽이에요.","작품의 재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u8_review_d#25','kor',2,2,'u8','','g2_2_kor_u8_review_d','unit_review','K2-2-u8-C13',4,'essay','teacher','토박이말 「미리내·으뜸·너울·갈무리」 가운데 하나를 골라 짧은 문장을 만드세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u8-C13","difficulty":4,"kind":"essay","stem":"토박이말 「미리내·으뜸·너울·갈무리」 가운데 하나를 골라 짧은 문장을 만드세요.","answer_guide":{"answer":"예: 우리 반은 청소를 끝내고 학급 문고를 깔끔하게 갈무리했다.","scoring_points":["토박이말을 하나 골랐어요","뜻에 맞게 문장을 만들었어요"]},"explanation":["짧은 문장이에요.","264쪽이에요.","뜻에 맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
